/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Inits the METALMSupplierVolumetricRebateHeader fields with default values.
/// </summary>
public void initValue()
{
    super();
    this.DocumentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    this.TransactionDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    this.Status = METALMSupplierVolumetricRebateStatus::Created;
    this.CurrencyCode = Ledger::accountingCurrency(CompanyInfo::find().RecId);
    
}

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// ValidateWrite method for METALMSupplierVolumetricRebateHeader records
    /// </summary>
    /// <returns>true if record is valid for write, otherwise false</returns>
    public boolean validateWrite()
    {
        boolean ret;

        if (!this.Number)
        {
            this.Number = NumberSeq::newGetNum(
                VendParameters::METnumRefALMSupplierVolumetricRebateNumber()).num();
        }

        ret = super();

        ret = ret && this.validateStatus();
       
        return ret;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// ValidateDelete method for METALMSupplierVolumetricRebateHeader records
    /// </summary>
    /// <returns>true if record is valid for delete, otherwise false</returns>
    public boolean validateDelete()
    {
        boolean ret;

